package app.noir.mobile;
import android.app.*;
import android.content.*;
import android.graphics.Typeface;
import android.os.Bundle;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;

public final class PersonActivity extends Activity {
    PhoneCredits credits;JSONObject person,source;LinearLayout body,films;volatile boolean closed;
    @Override public void onCreate(Bundle state){super.onCreate(state);credits=new PhoneCredits(NoirApp.data);try{person=new JSONObject(getIntent().getStringExtra("person"));source=new JSONObject(getIntent().getStringExtra("source"));}catch(Exception e){finish();return;}getWindow().setStatusBarColor(MainActivity.BLACK);getWindow().setNavigationBarColor(MainActivity.BLACK);ScrollView scroll=new ScrollView(this);scroll.setBackgroundColor(MainActivity.BLACK);scroll.setFillViewport(true);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(20),dp(20),dp(20),dp(36));scroll.addView(body);setContentView(scroll);TextView back=text("‹ Back",16,MainActivity.GOLD);back.setPadding(0,dp(8),0,dp(20));back.setOnClickListener(v->finish());body.addView(back);LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);header.addView(PhoneCredits.photo(this,credits,person.optString("photo"),false),new LinearLayout.LayoutParams(dp(116),dp(150)));TextView name=text(person.optString("name"),28,MainActivity.WHITE);name.setTypeface(null,Typeface.BOLD);name.setPadding(dp(20),0,0,0);header.addView(name,new LinearLayout.LayoutParams(0,-2,1));body.addView(header);films=new LinearLayout(this);films.setOrientation(LinearLayout.VERTICAL);body.addView(films);ProgressBar loading=new ProgressBar(this);films.addView(loading,new LinearLayout.LayoutParams(dp(40),dp(64)));PhoneCredits.WORK.execute(()->{JSONArray titles=credits.filmography(person,source);Map<String,boolean[]> marks=new HashMap<>();for(JSONObject item:DataStore.objects(credits.data.items())){String id=PhoneCredits.imdb(item);boolean[] mark=marks.get(id);if(mark==null){mark=new boolean[]{false,true};marks.put(id,mark);}mark[0]|=item.optBoolean("inLibrary",true);mark[1]&=DataStore.watched(item);}for(JSONObject title:DataStore.objects(titles)){boolean[] mark=marks.get(PhoneCredits.imdb(title));DataStore.put(title,"libraryMark",mark==null?0:mark[1]?2:mark[0]?1:0);}runOnUiThread(()->{if(!closed&&!isFinishing())render(titles);});});Loc.apply(this);Motion.riseIn(header,0);}
    int dp(int n){return PhoneCredits.dp(this,n);}TextView text(String s,int size,int color){return PhoneCredits.text(this,s,size,color);}
    void render(JSONArray titles){films.removeAllViews();if(titles.length()==0){TextView empty=text("No filmography is available yet.",15,MainActivity.MUTED);empty.setPadding(0,dp(24),0,0);films.addView(empty);return;}TextView known=text("Known for",21,MainActivity.WHITE);known.setTypeface(null,Typeface.BOLD);known.setPadding(0,dp(26),0,dp(14));films.addView(known);HorizontalScrollView rail=new HorizontalScrollView(this);rail.setHorizontalScrollBarEnabled(false);LinearLayout cards=new LinearLayout(this);rail.addView(cards);films.addView(rail);for(int n=0;n<Math.min(10,titles.length());n++){JSONObject title=titles.optJSONObject(n);LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(0,0,dp(12),0);card.addView(PhoneCredits.photo(this,credits,title.optString("poster"),false),new LinearLayout.LayoutParams(dp(112),dp(166)));TextView label=text(title.optString("name"),13,MainActivity.WHITE);label.setMaxLines(2);label.setPadding(0,dp(8),0,0);card.addView(label,new LinearLayout.LayoutParams(dp(112),dp(46)));card.setOnClickListener(v->open(title));Motion.card(card);cards.addView(card);}TextView heading=text("Filmography",21,MainActivity.WHITE);heading.setTypeface(null,Typeface.BOLD);heading.setPadding(0,dp(24),0,dp(8));films.addView(heading);String year=null;for(JSONObject title:DataStore.objects(titles)){String value=title.optString("year");if(!value.equals(year)){year=value;TextView group=text(value.isEmpty()?"Unknown year":value,16,MainActivity.GOLD);group.setPadding(0,dp(18),0,dp(8));films.addView(group);}boolean saved=title.optInt("libraryMark")>0,watched=title.optInt("libraryMark")==2;LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.VERTICAL);row.setPadding(dp(14),dp(14),dp(14),dp(14));row.setBackground(MainActivity.bg(MainActivity.PANEL,dp(12)));row.addView(text(title.optString("name"),16,MainActivity.WHITE));String mark=watched?Loc.t("✓ Watched"):saved?Loc.t("In your library"):"";if(!mark.isEmpty())row.addView(text(mark,12,MainActivity.GOLD));row.setOnClickListener(v->open(title));Motion.card(row);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(4),0,dp(4));films.addView(row,lp);}Motion.fadeIn(films);}
    void open(JSONObject title){startActivity(new Intent(this,DiscoverActivity.class).putExtra("title",title.toString()));}
    @Override protected void onDestroy(){closed=true;super.onDestroy();}
}
